import React from 'react';
import { Link } from 'gatsby';
import * as styles from './Pagination.module.scss';

interface Props {
  currentPage: number;
  totalPages: number;
  url: string;
  theme?: {
    colors: {
      grey: {
        light: string;
      };
      primary: string;
      white: string;
    };
  };
}

const Pagination = (props: Props) => {
  const { currentPage, totalPages, url, theme } = props;
  const isFirst = currentPage === 1;
  const isLast = currentPage === totalPages;
  const prevPage = currentPage - 1 === 1 ? `/${url}/` : `/${url}/${(currentPage - 1).toString()}`;
  const nextPage = `/${url}/${(currentPage + 1).toString()}`;

  const styleVars: React.CSSProperties = {
    ['--pagination-text-color' as any]: theme?.colors.grey.light,
    ['--pagination-hover-bg' as any]: theme?.colors.primary,
    ['--pagination-hover-color' as any]: theme?.colors.white,
  };

  return totalPages > 1 ? (
    <div className={styles.paginationContainer}>
      <div className={styles.paginationContent} style={styleVars}>
        {!isFirst && (
          <Link className={`${styles.pageNumbers} prev`} to={prevPage} rel="prev">
            ← Prev
          </Link>
        )}
        {Array.from({ length: totalPages }, (_, i) => (
          <Link
            className={`${styles.pageNumbers} ${currentPage === i + 1 ? 'current' : ''}`}
            key={`pagination-number${i + 1}`}
            to={`/${url}/${i === 0 ? '' : i + 1}`}
          >
            {i + 1}
          </Link>
        ))}
        {!isLast && (
          <Link className={`${styles.pageNumbers} next`} to={nextPage} rel="next">
            Next →
          </Link>
        )}
      </div>
    </div>
  ) : null;
};

export default Pagination;
