import React from 'react';
import { graphql } from 'gatsby';
import { PostGraphqlResponse } from '../../types';
import PageTitle from '../components/PageTitle';
import Layout from '../components/Layout';
import Header from '../components/Header';
import SectionTitle from '../components/SectionTitle';
import Wrapper from '../components/Wrapper';
import Content from '../components/Content';
import Article from '../components/Article';
import Pagination from '../components/Pagination';

interface Props {
  data: PostGraphqlResponse;
  pageContext: {
    currentPage: number;
    totalPages: number;
  };
}

export default class BlogPage extends React.Component<Props> {
  public render() {
    const { currentPage, totalPages } = this.props.pageContext;

    const { data } = this.props;
    const { edges } = data.allMarkdownRemark;

    return (
      <Layout>
        <PageTitle title="Blog" />
        <Header>
          <SectionTitle uppercase={true}>All the posts</SectionTitle>
        </Header>
        <Wrapper>
          <Content>
            {edges.map((post) => (
              <Article
                title={post.node.frontmatter.title}
                date={post.node.frontmatter.date}
                excerpt={post.node.excerpt}
                timeToRead={post.node.timeToRead}
                slug={post.node.fields.slug}
                category={post.node.frontmatter.category}
                key={post.node.fields.slug}
              />
            ))}
            <Pagination currentPage={currentPage} totalPages={totalPages} url={'blog'} />
          </Content>
        </Wrapper>
      </Layout>
    );
  }
}
export const BlogQuery = graphql`
  query ($skip: Int!, $limit: Int!) {
    allMarkdownRemark(sort: {frontmatter: {date: DESC}}, limit: $limit, skip: $skip) {
      totalCount
      edges {
        node {
          fields {
            slug
          }
          frontmatter {
            title
            date(formatString: "DD.MM.YYYY")
            category
          }
          excerpt(pruneLength: 200)
          timeToRead
        }
      }
    }
  }
`;
